import {createCanvas,loadImage,PDFDocument} from '@napi-rs/canvas';
import {chromium} from 'playwright';
import {readFile,writeFile} from 'node:fs/promises';
import {execFileSync} from 'node:child_process';
import {startStaticServer} from '../../test/support/static-server.js';
import {openBrowserPage,assertNoBrowserErrors,closeBrowserWithEvidence,saveBrowserEvidence} from '../../test/support/browser.js';
const dir=new URL('./',import.meta.url),width=120,height=100;
const variants=[...['source-over','multiply','screen','difference'].map(mode=>({id:mode,kind:'blend',mode})),... [0,8].map(blur=>({id:`shadow-${blur}`,kind:'shadow',blur}))];
function draw(context,v){
 context.fillStyle='white';context.fillRect(0,0,120,100);context.save();
 if(v.kind==='blend'){
  context.fillStyle='rgba(40,150,200,0.55)';context.fillRect(10,10,75,75);
  context.globalCompositeOperation=v.mode;context.globalAlpha=.65;context.fillStyle='rgba(210,70,45,0.6)';context.fillRect(40,30,70,60);
 }else{
  context.shadowColor='rgba(30,60,90,0.5)';context.shadowOffsetX=15;context.shadowOffsetY=8;context.shadowBlur=v.blur;
  context.globalAlpha=.65;context.fillStyle='rgba(210,70,45,0.6)';context.fillRect(20,20,40,40);
 }
 context.restore();
}
function expected(mode){
 const background=[40,150,200].map(c=>c*.55+255*.45),source=[210,70,45],alpha=.6*.65;
 return [...source.map((c,i)=>{
  const b=background[i],mixed=mode==='multiply'?b*c/255:mode==='screen'?b+c-b*c/255:mode==='difference'?Math.abs(b-c):c;
  return Math.round(alpha*mixed+(1-alpha)*b);
 }),255];
}
function rgba(canvas,x,y){return [...canvas.getContext('2d').getImageData(x,y,1,1).data];}
async function decoded(buffer){const canvas=createCanvas(width,height);canvas.getContext('2d').drawImage(await loadImage(buffer),0,0);return canvas;}
const html=`<!doctype html><title>Private effect probe</title><div id="status">Ready</div><script>window.draw=${draw};</script>`;
await writeFile(new URL('index.html',dir),html);let server,browser;const results=[];
try{
 server=await startStaticServer(new URL('../../',import.meta.url).pathname);browser=await chromium.launch({headless:true});
 const opened=await openBrowserPage(browser,`${server.baseUrl}.artifacts/paint-effects-study/index.html`,{waitFor:()=>document.getElementById('status').textContent==='Ready'});
 for(const variant of variants){
  const canvas=createCanvas(width,height);draw(canvas.getContext('2d'),variant);const png=canvas.toBuffer('image/png');await writeFile(new URL(`${variant.id}.png`,dir),png);
  const doc=new PDFDocument(),context=doc.beginPage(width,height);draw(context,variant);doc.endPage();const pdf=doc.close();await writeFile(new URL(`${variant.id}.pdf`,dir),pdf);
  execFileSync('pdftoppm',['-r','72','-singlefile','-png',new URL(`${variant.id}.pdf`,dir).pathname,new URL(`${variant.id}-pdf`,dir).pathname],{stdio:'pipe'});
  const pdfCanvas=await decoded(await readFile(new URL(`${variant.id}-pdf.png`,dir)));
  const data=await opened.page.evaluate(v=>{const c=document.createElement('canvas');c.width=120;c.height=100;window.draw(c.getContext('2d'),v);return c.toDataURL();},variant);
  const browserPNG=Buffer.from(data.split(',')[1],'base64');await writeFile(new URL(`${variant.id}-browser.png`,dir),browserPNG);const browserCanvas=await decoded(browserPNG);
  const points=variant.kind==='blend'?[[50,50]]:[[70,50],[64,64],[74,50],[80,50],[50,72]];
  const pixels=points.map(([x,y])=>({x,y,native:rgba(canvas,x,y),browser:rgba(browserCanvas,x,y),pdf:rgba(pdfCanvas,x,y),...(variant.kind==='blend'?{expected:expected(variant.mode)}:{})}));
  const native=canvas.getContext('2d').getImageData(0,0,width,height).data,browse=browserCanvas.getContext('2d').getImageData(0,0,width,height).data;
  let mismatchPixels=0,maxChannelDelta=0;for(let i=0;i<native.length;i+=4){let difference=false;for(let j=0;j<4;j++){const delta=Math.abs(native[i+j]-browse[i+j]);difference ||= delta!==0;maxChannelDelta=Math.max(maxChannelDelta,delta);}mismatchPixels+=difference;}
  results.push({...variant,pixels,nativeVsBrowser:{mismatchPixels,maxChannelDelta},pdfContainsImage:/\/Subtype\s*\/Image\b/.test(pdf.toString('latin1'))});
 }
 assertNoBrowserErrors(opened.errors,'Paint effects private probe');await opened.page.close();
 await writeFile(new URL('results.json',dir),JSON.stringify({privateInvestigation:true,publicSupport:false,width,height,results},null,2)+'\n');
 console.log(JSON.stringify(results,null,2));
}catch(error){await saveBrowserEvidence(browser,error);throw error;}finally{await closeBrowserWithEvidence(browser);await server?.close();}
